/**
 * Opening book — known positions → book continuations + opening name.
 *
 * Data: src/config/openings.json, generated by scripts/build-book.mjs
 * from the vendored lichess-org/chess-openings TSV files in data/ (CC0).
 * Position keys are "<placement> <turn>" (first two FEN fields), so any
 * move order reaching the same position — transpositions — shares one
 * entry. Lookups are plain object hits; the UCI strings are split into
 * Sets lazily on first use.
 */

import openings from "../config/openings.json" with { type: "json" };

interface BookPosition {
  /** Space-separated UCI continuations known for this position. */
  m?: string;
  /** Index into `names`: the opening this position belongs to. */
  n?: number;
}

interface BookFile {
  names: { eco: string; name: string }[];
  positions: Record<string, BookPosition>;
}

const book = openings as unknown as BookFile;

export interface OpeningInfo {
  name: string;
  eco: string;
}

/** Lookup key of a FEN: placement + turn. */
export function positionKey(fen: string): string {
  return fen.split(" ").slice(0, 2).join(" ");
}

const moveSets = new Map<string, Set<string>>();

function movesAt(key: string): Set<string> {
  let set = moveSets.get(key);
  if (!set) {
    const entry = book.positions[key];
    set = entry?.m ? new Set(entry.m.split(" ")) : new Set<string>();
    moveSets.set(key, set);
  }
  return set;
}

/** All book continuations (UCI) from this position; [] if unknown. */
export function bookMoves(fen: string): string[] {
  return [...movesAt(positionKey(fen))];
}

/** True when `uci` is a known opening move from this position. */
export function isBookMove(fen: string, uci: string): boolean {
  return movesAt(positionKey(fen)).has(uci);
}

/** Opening name + ECO code for a position; null outside the book. */
export function openingAt(fen: string): OpeningInfo | null {
  const entry = book.positions[positionKey(fen)];
  const named = entry?.n !== undefined ? book.names[entry.n] : undefined;
  return named ? { name: named.name, eco: named.eco } : null;
}
